function evidence = f90_xmech07_extract_candidate_evidence( ...
        candidatePath, outDir)
%F90_XMECH07_EXTRACT_CANDIDATE_EVIDENCE Public-contract candidate adapter.
arguments
    candidatePath (1,1) string
    outDir (1,1) string
end
[taskRoot, sharedRoot] = localRoots("F90-XMECH-07");
addpath(sharedRoot, "-begin");
cleanup = onCleanup(@() rmpath(sharedRoot)); %#ok<NASGU>
official = jsondecode(fileread(simuverity_official_scenarios_path()));
spec = struct( ...
    "schema", "simuverity.f90-xmech07-evidence.v1", ...
    "task_id", "F90-XMECH-07", ...
    "scenarios", official.scenarios, ...
    "output_contract", localOutputs, ...
    "input_builder", @localInputs, ...
    "requested_input_builder", @localInputs, ...
    "stop_time", @(~, ~) double(official.simulation.stop_s), ...
    "postprocess", @localPostprocess, ...
    "static_audit", @localAudit, ...
    "evidence_sample_s", 0.01);
evidence = simuverity_run_candidate_evidence( ...
    candidatePath, outDir, spec);
end

function rows = localOutputs
names = ["box_state","command_state","input_contact","output_contact"];
widths = [6 6 8 8];
rows = localRows(names, widths);
end

function inputs = localInputs(scenario, ~)
inputs = rmfield(scenario, "id");
end

function row = localPostprocess(row, outputs, ~, ~)
row.outputs = outputs;
row.valid = row.output_contract.all_required_pass;
end

function audit = localAudit(model, spec)
structure = simuverity_candidate_structure( ...
    model, string({spec.output_contract.name})');
semantic = structure.semantic_types;
multibody = nnz(contains(semantic, ["multibody","simscape"]));
contact = nnz(contains(semantic, ["spatial contact","contact force"]));
actuation = nnz(contains(semantic, ["joint actuator","force source"]));
audit = struct( ...
    "physical_connection_block_count", ...
        structure.physical_connection_block_count, ...
    "multibody_or_physical_block_count", multibody, ...
    "contact_mechanism_count", contact, ...
    "actuation_mechanism_count", actuation, ...
    "connected_public_output_count", ...
        structure.connected_output_count, ...
    "signal_cycle_present", structure.signal_cycle_present, ...
    "core_path_qualified", ...
        structure.connected_output_count == ...
            numel(spec.output_contract) && ...
        structure.nontrivial_output_source_count == ...
            numel(spec.output_contract) && ...
        structure.physical_connection_block_count >= 4 && ...
        multibody >= 2 && contact >= 1 && actuation >= 1);
end

function rows = localRows(names, widths)
rows = repmat(struct("name","","evidence_name","","width",0, ...
    "interpolation","linear"), numel(names), 1);
for k = 1:numel(names)
    rows(k).name = names(k);
    rows(k).evidence_name = names(k);
    rows(k).width = widths(k);
end
end

function [taskRoot, sharedRoot] = localRoots(taskId)
scriptRoot = fileparts(mfilename("fullpath"));
tasksRoot = fileparts(scriptRoot);
sharedRoot = fullfile(tasksRoot, "_shared");
repoRoot = tasksRoot;
for k = 1:3, repoRoot = fileparts(repoRoot); end
taskRoot = string(getenv("SIMUVERITY_TASK_ROOT"));
end
